// 在此修改服务地址和模型实际路径，不从Webhook接收服务URL或密钥。
const config = { comfyUrl: 'http://117.50.171.219:8188', unet: 'acestep1.5/acestep_v1.5_turbo.safetensors', clip1: 'qwen_0.6b_ace15.safetensors', clip2: 'qwen_1.7b_ace15.safetensors', vae: 'ace_1.5_vae.safetensors', maxPolls: 120 };
const input = $input.first().json;
const body = input.body || {};
const caption = String(body.caption || body.prompt || '').trim();
const rawLyrics = Array.isArray(body.lyrics) ? body.lyrics.map(row => typeof row === 'string' ? row : row?.text || '').join('\n') : String(body.lyrics || '');
const lyrics = rawLyrics.replace(/\[(?:\d+:\d+(?:\.\d+)?)\]/g, '').replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '').replace(/[—–]/g, ' ').trim();
if (!caption || !lyrics) throw new Error('caption/prompt和完整lyrics均为必填，歌词请独立传入。');
if (caption.length > 6000 || lyrics.length > 12000) throw new Error('提示词或歌词过长。');
function number(value, fallback, min, max, integer = false) { const n = value == null ? fallback : Number(value); if (!Number.isFinite(n) || n < min || n > max || (integer && !Number.isInteger(n))) throw new Error('数值参数超出范围：' + value); return n; }
const duration = number(body.duration, 60, 10, 120);
const bpm = number(body.bpm, 100, 30, 300, true);
const steps = number(body.steps, 8, 1, 20, true);
const seed = number(body.seed, Math.floor(Math.random() * 1000000000000), 0, Number.MAX_SAFE_INTEGER, true);
const language = String(body.language || 'en');
if (!['en','zh','ja','ko','es','fr','de','it','pt','ru','yue','unknown'].includes(language)) throw new Error('不支持的language，请在配置节点扩展已安装节点支持的语言。');
const keyscale = String(body.keyscale || 'C major');
if (!/^(?:C|C#|Db|D|D#|Eb|E|F|F#|Gb|G|G#|Ab|A|A#|Bb|B) (?:major|minor)$/.test(keyscale)) throw new Error('keyscale格式不正确，例如C major。');
const prompt = {
 '1': { class_type: 'UNETLoader', inputs: { unet_name: config.unet, weight_dtype: 'default' } },
 '2': { class_type: 'DualCLIPLoader', inputs: { clip_name1: config.clip1, clip_name2: config.clip2, type: 'ace', device: 'default' } },
 '3': { class_type: 'VAELoader', inputs: { vae_name: config.vae } },
 '6': { class_type: 'TextEncodeAceStepAudio1.5', inputs: { clip: ['2',0], tags: caption, lyrics, seed, bpm, duration, timesignature: '4', language, keyscale, generate_audio_codes: true, cfg_scale: 2, temperature: 0.85, top_p: 0.9, top_k: 0, min_p: 0 } },
 '7': { class_type: 'ModelSamplingAuraFlow', inputs: { model: ['1',0], shift: 3 } },
 '8': { class_type: 'ConditioningZeroOut', inputs: { conditioning: ['6',0] } },
 '9': { class_type: 'EmptyAceStep1.5LatentAudio', inputs: { seconds: duration, batch_size: 1 } },
 '10': { class_type: 'KSampler', inputs: { model: ['7',0], positive: ['6',0], negative: ['8',0], latent_image: ['9',0], seed, steps, cfg: 1, sampler_name: 'euler', scheduler: 'simple', denoise: 1 } },
 '11': { class_type: 'VAEDecodeAudio', inputs: { samples: ['10',0], vae: ['3',0] } },
 '12': { class_type: 'SaveAudio', inputs: { audio: ['11',0], filename_prefix: 'music-star-quest/full-song-' + seed } }
};
return [{ json: { ...config, caption, lyrics, duration, bpm, seed, language, keyscale, payload: { prompt, client_id: 'n8n-full-song-' + $execution.id } } }];

const result = $input.first().json;
if (!result.prompt_id || (result.node_errors && Object.keys(result.node_errors).length)) throw new Error('ComfyUI未接受流程，请检查模型文件和缺失节点。');
return [{ json: { success: true, executionId: String($execution.id), promptId: result.prompt_id, workflowType: 'music', workflow: 'gene-music-full-song', status: 'submitted', alignmentStatus: 'not_generated', message: '整曲任务已提交，后台继续生成；executionId为n8n执行ID，promptId为ComfyUI任务ID。' } }];

const config = $('配置与构建ComfyUI API图').first().json;
const task = $('校验提交结果').first().json;
const history = $input.first().json;
const result = history[task.promptId];
const poll = $runIndex + 1;
if (result?.status?.status_str === 'error' || result?.status?.messages?.some(m => ['execution_error','execution_interrupted'].includes(m[0]))) throw new Error('ComfyUI任务失败或被中断：' + task.promptId);
const output = result?.outputs?.['12'];
const files = output?.audio || output?.audios || [];
const file = files.find(f => f.type === 'output' && /\.flac$/i.test(f.filename || ''));
if (file) {
 if (!file.filename || file.filename.includes('/') || file.filename.includes('\\') || String(file.subfolder || '').split('/').includes('..')) throw new Error('ComfyUI返回了非法文件路径。');
 const query = 'filename=' + encodeURIComponent(file.filename) + '&subfolder=' + encodeURIComponent(file.subfolder || '') + '&type=output';
 return [{ json: { executionId: task.executionId, promptId: task.promptId, ready: true, filename: file.filename, comfyAudioUrl: config.comfyUrl + '/view?' + query, duration: config.duration, seed: config.seed, lyrics: config.lyrics, poll } }];
}
if (result?.status?.completed) throw new Error('任务已结束但SaveAudio节点没有返回FLAC音频，请检查节点12。');
if (poll >= config.maxPolls) throw new Error('轮询达到上限；未取消GPU任务，请在ComfyUI确认其状态。promptId=' + task.promptId);
return [{ json: { executionId: task.executionId, promptId: task.promptId, ready: false, poll } }];

const meta = $('音频已就绪').item.json;
const bytes = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!bytes.length || bytes.subarray(0,4).toString('ascii') !== 'fLaC') throw new Error('下载内容不是有效FLAC文件头，请检查ComfyUI认证。');
const localFilename = 'full_song_' + String($execution.id).replace(/[^a-zA-Z0-9_-]/g, '') + '_' + Date.now() + '.flac';
return [{ json: { ...meta, localFilename, localFilePath: '/home/node/files/' + localFilename }, binary: $input.first().binary, pairedItem: { item: 0 } }];

const meta = $('校验歌曲文件').first().json;
// 复用现有/files读取流程；它读取本地文件，不负责从ComfyUI下载。
const url = 'http://117.50.218.161:5678/webhook/files?file=' + encodeURIComponent(meta.localFilename);
return [{ json: { success: true, status: 'completed', executionId: meta.executionId, promptId: meta.promptId, workflowType: 'music', filename: meta.localFilename, url, audio_url: url, music_filepath: url, comfyAudioUrl: meta.comfyAudioUrl, duration: meta.duration, durationSource: 'requested_not_measured', seed: meta.seed, lyrics: meta.lyrics, alignmentStatus: 'not_generated', backingStatus: 'not_generated', results: [{ url, filename: meta.localFilename }] } }];

